// Keep the pointer-following probe in a child process: shifting the pointer into
// the wrong register can fault inside C before Go can report an assertion.
func TestRegisterFuncFollowingPointer(t *testing.T) {
	if os.Getenv("FFI_REGISTER_POINTER_CHILD") != "1" {
		cmd := exec.Command(os.Args[0], "-test.run=^TestRegisterFuncFollowingPointer$", "-test.v")
		cmd.Env = append(os.Environ(), "FFI_REGISTER_POINTER_CHILD=1")
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("pointer probe: %v\n%s", err, out)
		}
		if !strings.Contains(string(out), "pointer probe passed") {
			t.Fatalf("missing child receipt: %s", out)
		}
		return
	}
	var call func(uint64, team12, uint64, *uint64) int32
	if err := ffi.RegisterFunc(&call, buildSym(t, registerFuncC, "follow")); err != nil {
		t.Fatal(err)
	}
	var out uint64
	if got := call(7, team12{0x11111111, 0x22222222, 0x33333333}, 13, &out); got != 19 || out != 0x66666666+20 {
		t.Fatalf("result=%d out=%#x", got, out)
	}
	t.Log("pointer probe passed")
}

